query:
mutation networkConfig ( $accountId:ID! $networkConfigDhcpUpdateSettingsInput:NetworkConfigDhcpUpdateSettingsInput! $networkConfigDhcpCreateOptionInput:NetworkConfigDhcpCreateOptionInput! $networkConfigDhcpUpdateOptionInput:NetworkConfigDhcpUpdateOptionInput! $networkConfigDhcpDeleteOptionInput:NetworkConfigDhcpDeleteOptionInput! $networkConfigDhcpSetOptionInput:NetworkConfigDhcpSetOptionInput! $networkConfigDhcpCreateRelayGroupInput:NetworkConfigDhcpCreateRelayGroupInput! $networkConfigDhcpUpdateRelayGroupInput:NetworkConfigDhcpUpdateRelayGroupInput! $networkConfigDhcpDeleteRelayGroupInput:NetworkConfigDhcpDeleteRelayGroupInput! $networkConfigDhcpSetRelayGroupInput:NetworkConfigDhcpSetRelayGroupInput! $networkConfigDnsUpdateSettingsInput:NetworkConfigDnsUpdateSettingsInput! $networkConfigDnsUpdateSiteSettingsInput:NetworkConfigDnsUpdateSiteSettingsInput! $networkConfigDnsRemoveSiteSettingsInput:NetworkConfigDnsRemoveSiteSettingsInput! $networkConfigDnsCreateForwardingRuleInput:NetworkConfigDnsCreateForwardingRuleInput! $networkConfigDnsUpdateForwardingRuleInput:NetworkConfigDnsUpdateForwardingRuleInput! $networkConfigDnsDeleteForwardingRuleInput:NetworkConfigDnsDeleteForwardingRuleInput! $networkConfigDnsSetForwardingRuleInput:NetworkConfigDnsSetForwardingRuleInput! $networkConfigDnsCreateServerSetInput:NetworkConfigDnsCreateServerSetInput! $networkConfigDnsUpdateServerSetInput:NetworkConfigDnsUpdateServerSetInput! $networkConfigDnsDeleteServerSetInput:NetworkConfigDnsDeleteServerSetInput! $networkConfigDnsSetServerSetInput:NetworkConfigDnsSetServerSetInput! $networkConfigDnsCreateSuffixSetInput:NetworkConfigDnsCreateSuffixSetInput! $networkConfigDnsUpdateSuffixSetInput:NetworkConfigDnsUpdateSuffixSetInput! $networkConfigDnsDeleteSuffixSetInput:NetworkConfigDnsDeleteSuffixSetInput! $networkConfigDnsSetSuffixSetInput:NetworkConfigDnsSetSuffixSetInput!) {
	networkConfig ( accountId:$accountId ) {
		dhcp {
			updateSettings ( input:$networkConfigDhcpUpdateSettingsInput   ) {
				settings {
					relay {
						enabled
						timeout
						group {
							id
							name
						}
					}
					leaseTime
				}
			}
			createOption ( input:$networkConfigDhcpCreateOptionInput   ) {
				option {
					id
					tag
					value
					description
					type
				}
			}
			updateOption ( input:$networkConfigDhcpUpdateOptionInput   ) {
				option {
					id
					tag
					value
					description
					type
				}
			}
			deleteOption ( input:$networkConfigDhcpDeleteOptionInput   ) {
				option {
					id
					tag
					value
					description
					type
				}
			}
			setOption ( input:$networkConfigDhcpSetOptionInput   ) {
				option {
					id
					tag
					value
					description
					type
				}
			}
			createRelayGroup ( input:$networkConfigDhcpCreateRelayGroupInput   ) {
				relayGroup {
					id
					name
					server
				}
			}
			updateRelayGroup ( input:$networkConfigDhcpUpdateRelayGroupInput   ) {
				relayGroup {
					id
					name
					server
				}
			}
			deleteRelayGroup ( input:$networkConfigDhcpDeleteRelayGroupInput   ) {
				relayGroup {
					id
					name
					server
				}
			}
			setRelayGroup ( input:$networkConfigDhcpSetRelayGroupInput   ) {
				relayGroup {
					id
					name
					server
				}
			}
		}
		dns {
			updateSettings ( input:$networkConfigDnsUpdateSettingsInput   ) {
				settings {
					primaryServer
					secondaryServer
					suffix
					acceptDnsRequestsOnLanInterfaceIp
				}
			}
			updateSiteSettings ( input:$networkConfigDnsUpdateSiteSettingsInput   ) {
				siteSettings {
					siteId
					primaryServer
					secondaryServer
					suffix
				}
			}
			removeSiteSettings ( input:$networkConfigDnsRemoveSiteSettingsInput   ) {
				siteSettings {
					siteId
					primaryServer
					secondaryServer
					suffix
				}
			}
			createForwardingRule ( input:$networkConfigDnsCreateForwardingRuleInput   ) {
				forwardingRule {
					id
					domain
					server
				}
			}
			updateForwardingRule ( input:$networkConfigDnsUpdateForwardingRuleInput   ) {
				forwardingRule {
					id
					domain
					server
				}
			}
			deleteForwardingRule ( input:$networkConfigDnsDeleteForwardingRuleInput   ) {
				forwardingRule {
					id
					domain
					server
				}
			}
			setForwardingRule ( input:$networkConfigDnsSetForwardingRuleInput   ) {
				forwardingRule {
					id
					domain
					server
				}
			}
			createServerSet ( input:$networkConfigDnsCreateServerSetInput   ) {
				dnsServerSet {
					id
					name
					server
					audit {
						updatedTime
						updatedBy {
							id
							name
							... on AdminRef {
								id
								name
							}
							... on ApiKeyRef {
								id
								name
							}
						}
					}
				}
			}
			updateServerSet ( input:$networkConfigDnsUpdateServerSetInput   ) {
				dnsServerSet {
					id
					name
					server
					audit {
						updatedTime
						updatedBy {
							id
							name
							... on AdminRef {
								id
								name
							}
							... on ApiKeyRef {
								id
								name
							}
						}
					}
				}
			}
			deleteServerSet ( input:$networkConfigDnsDeleteServerSetInput   ) {
				dnsServerSet {
					id
					name
					server
					audit {
						updatedTime
						updatedBy {
							id
							name
							... on AdminRef {
								id
								name
							}
							... on ApiKeyRef {
								id
								name
							}
						}
					}
				}
			}
			setServerSet ( input:$networkConfigDnsSetServerSetInput   ) {
				dnsServerSet {
					id
					name
					server
					audit {
						updatedTime
						updatedBy {
							id
							name
							... on AdminRef {
								id
								name
							}
							... on ApiKeyRef {
								id
								name
							}
						}
					}
				}
			}
			createSuffixSet ( input:$networkConfigDnsCreateSuffixSetInput   ) {
				dnsSuffixSet {
					id
					name
					suffix
					audit {
						updatedTime
						updatedBy {
							id
							name
							... on AdminRef {
								id
								name
							}
							... on ApiKeyRef {
								id
								name
							}
						}
					}
				}
			}
			updateSuffixSet ( input:$networkConfigDnsUpdateSuffixSetInput   ) {
				dnsSuffixSet {
					id
					name
					suffix
					audit {
						updatedTime
						updatedBy {
							id
							name
							... on AdminRef {
								id
								name
							}
							... on ApiKeyRef {
								id
								name
							}
						}
					}
				}
			}
			deleteSuffixSet ( input:$networkConfigDnsDeleteSuffixSetInput   ) {
				dnsSuffixSet {
					id
					name
					suffix
					audit {
						updatedTime
						updatedBy {
							id
							name
							... on AdminRef {
								id
								name
							}
							... on ApiKeyRef {
								id
								name
							}
						}
					}
				}
			}
			setSuffixSet ( input:$networkConfigDnsSetSuffixSetInput   ) {
				dnsSuffixSet {
					id
					name
					suffix
					audit {
						updatedTime
						updatedBy {
							id
							name
							... on AdminRef {
								id
								name
							}
							... on ApiKeyRef {
								id
								name
							}
						}
					}
				}
			}
		}
	}	
}
